-- "After the documents" steps say what we do: we register, pay and submit.
-- Only what the law requires in person stays with the student (by: "you").
UPDATE countries SET rules = jsonb_set(rules, '{steps}', '[{"key": "apply", "by": "us", "title": "We register you on the university portal, pay the application fee and submit your application"}, {"key": "admission", "by": "us", "title": "We track the decision and send you the admission letter as soon as it arrives"}, {"key": "universitaly", "by": "us", "title": "We file your Universitaly pre-enrolment for the study visa"}, {"key": "dsu_scholarship", "by": "us", "title": "We apply for the regional DSU scholarship for you (if you are eligible)"}, {"key": "visa_file", "by": "us", "title": "We book your type D visa appointment in Tashkent and prepare the full visa file"}, {"key": "visa", "by": "you", "title": "You go to the visa appointment in person for fingerprints and the interview"}]'::jsonb) WHERE code = 'IT';
UPDATE countries SET rules = jsonb_set(rules, '{steps}', '[{"key": "apply", "by": "us", "title": "We submit your application on the university portal or through uni-assist and pay the fee (EUR 75 for the first programme, EUR 30 for each additional one per semester)"}, {"key": "admission", "by": "us", "title": "We track the decision and send you the admission letter (Zulassungsbescheid)"}, {"key": "blocked_account", "by": "you", "title": "Blocked account (Sperrkonto): we fill in the application; you confirm your identity and transfer the amount the German government sets for the visa"}, {"key": "visa_file", "by": "us", "title": "We book your national (D) visa appointment at the German Embassy in Tashkent and prepare the visa file"}, {"key": "visa", "by": "you", "title": "You go to the visa appointment in person for fingerprints and the interview"}, {"key": "enrol", "by": "us", "title": "We arrange your health insurance and enrolment at the university"}]'::jsonb) WHERE code = 'DE';
UPDATE countries SET rules = jsonb_set(rules, '{steps}', '[{"key": "apply", "by": "us", "title": "We fill in and submit your Common App or university application and pay the application fee"}, {"key": "admission", "by": "us", "title": "We track the admission decision"}, {"key": "i20", "by": "us", "title": "We send your proof of funds to the university so it issues your Form I-20"}, {"key": "sevis", "by": "us", "title": "We pay your SEVIS I-901 fee"}, {"key": "visa_file", "by": "us", "title": "We fill in your DS-160 form and book your F-1 visa interview in Tashkent"}, {"key": "visa", "by": "you", "title": "You go to the F-1 visa interview in person; we prepare you for it"}]'::jsonb) WHERE code = 'US';
